class StudentRecordManager:
    def __init__(self):
        # Initialize an empty dictionary to store student records
        self.students = {}

    def add_student(self, student_id, name, age, grade):
        # Add a new student to the dictionary
        self.students[student_id] = {
            'name': name,
            'age': age,
            'grade': grade
        }

    def remove_student(self, student_id):
        # Remove a student from the dictionary
        if student_id in self.students:
            del self.students[student_id]
        else:
            print(f"Student with ID {student_id} not found.")

    def get_student(self, student_id):
        # Retrieve a student's information
        if student_id in self.students:
            return self.students[student_id]
        else:
            print(f"Student with ID {student_id} not found.")
            return None

    def list_students(self):
        # List all students in the dictionary
        return list(self.students.values())

    def update_student(self, student_id, name=None, age=None, grade=None):
        # Update a student's information
        if student_id in self.students:
            if name:
                self.students[student_id]['name'] = name
            if age:
                self.students[student_id]['age'] = age
            if grade:
                self.students[student_id]['grade'] = grade
        else:
            print(f"Student with ID {student_id} not found.")
